def writeSleepEnter(typedString):
    pyautogui.write(typedString)
    time.sleep(round(random.uniform(0, 1), 10))
    # pyautogui.press('enter')


def sleepRandom(smallInt, largeInt):
    sleep = round(random.uniform(smallInt, largeInt), 10)
    print(formatHumanTimeString(sleep))
    time.sleep(sleep)
    
    if (random.randint(1, 1000) > 950):
        sleepRandom(1, 2)
        
    # if (random.randint(1, 1000) > 975):
    #     sleepRandom(5, 10)
        
    # if (random.randint(1, 1000) > 985):
    #     sleepRandom(5, 20)


def formatHumanTimeString(seconds):
    timeLeftMin = round((seconds) // 60)
    timeLeftSec = ("0" if ((seconds) % 60) <
                   10 else "") + str(round(seconds % 60, 5))
    return str(timeLeftMin) + ":" + str(timeLeftSec)

def copyTable(topLeft, otherProgram, redeemLocation, clearLocation):
    pyautogui.moveTo(topLeft[0], topLeft[1])
    pyautogui.leftClick()
    pyautogui.leftClick()
    pyautogui.keyDown('shift')
    pyautogui.keyDown('ctrl')
    pyautogui.press('right', 200)
    pyautogui.keyUp('shift')
    pyautogui.press('c')
    pyautogui.keyUp('ctrl')
    pyautogui.leftClick(otherProgram[0], otherProgram[1])
    pyautogui.press('pagedown')
    pyautogui.press('pagedown')
    pyautogui.press('enter')
    pyautogui.keyDown('ctrl')
    pyautogui.press('v')
    pyautogui.keyUp('ctrl')
    
    # pyautogui.leftClick(checkLocation[0], checkLocation[1])
    # sleepRandom(0.25, 1)
    # pictureLocation = pyautogui.locateOnScreen('Claimnow.png', confidence=0.9)
    # pyautogui.leftClick(pictureLocation[0]+15, pictureLocation[1]+15)
    # sleepRandom(2, 3)
    
    sleepRandom(5, 15)
    # pyautogui.leftClick(urlLocation[0], urlLocation[1])
    pyautogui.leftClick(redeemLocation[0], redeemLocation[1])
    # pyautogui.press('enter')
    sleepRandom(3, 5)
    pyautogui.leftClick(clearLocation[0], clearLocation[1])
    sleepRandom(3, 5)
    pyautogui.click(topLeft[0], topLeft[1])
    pyautogui.press('home')
    sleepRandom(0.25, 1)


